package ru.neverland.townyjustice;

import java.util.*;
import java.nio.charset.StandardCharsets;

/** Review records never change a sentence, payment, capture or due date. */
public final class JusticeDossiers {
    private JusticeDossiers() {}
    public enum Outcome { OPEN, UPHELD, RECONSIDER }
    public static String text(String value,int max){if(value==null||value.strip().length()<5||value.length()>max||value.chars().anyMatch(c->Character.isISOControl(c)||c=='§'||c=='&'))throw new IllegalArgumentException("Текст: 5–"+max+" символов, без переносов и цветовых кодов");return value.strip();}
    public record Evidence(String id,UUID addedBy,long at,String source,String reference,String description){
        public Evidence{Objects.requireNonNull(addedBy);description=text(description,600);if(at<0||source==null||!Set.of("NOTE","CRIME").contains(source)||reference==null||id==null)throw new IllegalArgumentException("Неверные сведения");UUID.fromString(reference);if(!id.equals(source.toLowerCase(Locale.ROOT)+":"+reference))throw new IllegalArgumentException("Неверный ID сведений");}
        public static Evidence note(UUID caseId,UUID actor,String description,long now){description=text(description,600);UUID id=UUID.nameUUIDFromBytes((caseId+"/"+actor+"/"+description).getBytes(StandardCharsets.UTF_8));return new Evidence("note:"+id,actor,now,"NOTE",id.toString(),description);}
    }
    public record Appeal(UUID id,UUID actor,String reason,long at,Outcome outcome,UUID reviewer,String decision,long reviewed){
        public Appeal{Objects.requireNonNull(id);Objects.requireNonNull(actor);Objects.requireNonNull(outcome);reason=text(reason,600);if(at<0||reviewed<0||decision==null)throw new IllegalArgumentException("Неверная апелляция");if(outcome==Outcome.OPEN){if(reviewer!=null||!decision.isEmpty()||reviewed!=0)throw new IllegalArgumentException("Открытая апелляция уже решена");}else{Objects.requireNonNull(reviewer);decision=text(decision,600);if(actor.equals(reviewer)||reviewed<at)throw new IllegalArgumentException("Нельзя рассмотреть свою апелляцию");}}
        public Appeal decide(UUID reviewer,Outcome result,String explanation,long now){if(outcome!=Outcome.OPEN||result==Outcome.OPEN)throw new IllegalArgumentException("Апелляция уже рассмотрена");return new Appeal(id,actor,reason,at,result,reviewer,explanation,now);}
    }
    public record Entry(UUID id,UUID actor,String action,String detail,long at){public Entry{Objects.requireNonNull(id);Objects.requireNonNull(actor);detail=text(detail,600);if(!Set.of("ASSIGNED","EVIDENCE","APPEALED","UPHELD","RECONSIDER").contains(action)||at<0)throw new IllegalArgumentException("Неверная запись истории");}}
    public record Dossier(UUID caseId,UUID town,UUID subject,UUID assigned,Map<String,Evidence> evidence,List<Appeal> appeals,List<Entry> history,long revision){
        public Dossier{Objects.requireNonNull(caseId);Objects.requireNonNull(town);Objects.requireNonNull(subject);evidence=Map.copyOf(evidence);appeals=List.copyOf(appeals);history=List.copyOf(history);if(evidence.size()>32||appeals.size()>10||history.size()>128||revision<0)throw new IllegalArgumentException("Предел записей дела достигнут");for(var e:evidence.entrySet())if(!e.getKey().equals(e.getValue().id()))throw new IllegalArgumentException("ID сведений не совпадает");var ids=new HashSet<UUID>();int open=0;for(var a:appeals){if(!ids.add(a.id())||!a.actor().equals(subject))throw new IllegalArgumentException("Чужая или повторная апелляция");if(a.outcome()==Outcome.OPEN)open++;}if(open>1)throw new IllegalArgumentException("У дела уже есть открытая апелляция");ids.clear();for(var h:history)if(!ids.add(h.id()))throw new IllegalArgumentException("Повтор истории");}
        public static Dossier empty(UUID id,UUID town,UUID subject){return new Dossier(id,town,subject,null,Map.of(),List.of(),List.of(),0);}
        private Dossier update(UUID assignee,Map<String,Evidence> facts,List<Appeal> appeals,UUID actor,String action,String detail,long now){var log=new ArrayList<>(history);log.add(new Entry(UUID.randomUUID(),actor,action,detail,now));return new Dossier(caseId,town,subject,assignee,facts,appeals,log,Math.incrementExact(revision));}
        public Dossier assign(UUID actor,UUID assignee,long now){Objects.requireNonNull(assignee);if(assignee.equals(assigned))return this;return update(assignee,evidence,appeals,actor,"ASSIGNED","Назначен ответственный: "+assignee,now);}
        public Dossier add(Evidence fact){var old=evidence.get(fact.id());if(old!=null){if(!old.source().equals(fact.source())||!old.reference().equals(fact.reference())||!old.description().equals(fact.description()))throw new IllegalArgumentException("ID сведений уже связан с другими данными");return this;}var next=new LinkedHashMap<>(evidence);next.put(fact.id(),fact);return update(assigned,next,appeals,fact.addedBy(),"EVIDENCE","Добавлены сведения: "+fact.id(),fact.at());}
        public Dossier appeal(UUID actor,String reason,long now){if(!subject.equals(actor))throw new IllegalArgumentException("Апелляцию подаёт участник дела");if(appeals.stream().anyMatch(a->a.outcome()==Outcome.OPEN))throw new IllegalArgumentException("Апелляция уже ожидает рассмотрения");var next=new ArrayList<>(appeals);next.add(new Appeal(UUID.randomUUID(),actor,reason,now,Outcome.OPEN,null,"",0));return update(assigned,evidence,next,actor,"APPEALED",reason,now);}
        public Dossier decide(UUID actor,Outcome result,String explanation,long now){var next=new ArrayList<>(appeals);int index=-1;for(int i=0;i<next.size();i++)if(next.get(i).outcome()==Outcome.OPEN){index=i;break;}if(index<0)throw new IllegalArgumentException("Нет открытой апелляции");next.set(index,next.get(index).decide(actor,result,explanation,now));return update(assigned,evidence,next,actor,result.name(),explanation,now);}
    }
    public record State(Map<UUID,Dossier> dossiers,long revision){
        public State{dossiers=Map.copyOf(dossiers);if(dossiers.size()>10000||revision<0)throw new IllegalArgumentException("Журнал разбирательств заполнен");var sources=new HashMap<String,UUID>();for(var entry:dossiers.entrySet()){var d=entry.getValue();if(!entry.getKey().equals(d.caseId()))throw new IllegalArgumentException("ID дела не совпадает");for(var e:d.evidence().values())if(e.source().equals("CRIME")&&sources.putIfAbsent(e.id(),d.caseId())!=null)throw new IllegalArgumentException("Происшествие уже закреплено за другим делом");}}
        public static State empty(){return new State(Map.of(),0);}
        public State put(Dossier value){var old=dossiers.get(value.caseId());if(old!=null&&(!old.town().equals(value.town())||!old.subject().equals(value.subject())))throw new IllegalArgumentException("Дело изменило участников");if(value.equals(old))return this;if(value.revision()!=(old==null?1:Math.incrementExact(old.revision())))throw new IllegalArgumentException("Версия дела изменилась");var next=new HashMap<>(dossiers);next.put(value.caseId(),value);return new State(next,Math.incrementExact(revision));}
    }
}
